def maximum_active_after_one_trade(s):
    active=s.count('1');previous=None;gain=0;index=0
    while index<len(s):
        end=index+1
        while end<len(s) and s[end]==s[index]:end+=1
        if s[index]=='0':
            length=end-index
            if previous is not None:gain=max(gain,previous+length)
            previous=length
        index=end
    return active+gain

